args.sql:
SELECT 
    ROUND(CAST(
        CAST((stellarprops->'physical'->>'Mass_Value') AS numeric) * CAST('1.98847e30' AS numeric) / 
        ((4.0/3.0) * CAST('3.14159265358979' AS numeric) * 
         POWER(CAST((stellarprops->'physical'->>'Radius_Value') AS numeric) * CAST('6.957e8' AS numeric), 3)
        ) AS numeric
    ), 0) as stellar_density_kg_m3
FROM stars 
WHERE hostplname = 'alf Tau';

